-- 基线迁移：由历史迁移重放得到的最终结构（001_baseline.sql 至 001_baseline.sql）。
CREATE TABLE qa_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),site_id TEXT NOT NULL,data_epoch TEXT NOT NULL);
CREATE TABLE qa_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),version INTEGER NOT NULL,policy_json TEXT NOT NULL);
CREATE TABLE conversations(conversation_id TEXT PRIMARY KEY,site_id TEXT NOT NULL,data_epoch TEXT NOT NULL,visitor_subject TEXT NOT NULL,language TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL,history_generation INTEGER NOT NULL,expires_at TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',summary_hash TEXT NOT NULL DEFAULT '',summary_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE messages(message_id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,ordinal INTEGER NOT NULL,role TEXT NOT NULL,text TEXT NOT NULL,turn_id TEXT NOT NULL,revision INTEGER NOT NULL,token_count INTEGER NOT NULL DEFAULT 0, model_text TEXT NOT NULL DEFAULT '', agent_messages_json TEXT,UNIQUE(conversation_id,ordinal));
CREATE TABLE turns(turn_id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,site_id TEXT NOT NULL,data_epoch TEXT NOT NULL,visitor_subject TEXT NOT NULL,language TEXT NOT NULL,turn_json TEXT NOT NULL,question TEXT NOT NULL,canonical_question TEXT NOT NULL DEFAULT '',memory_hash TEXT NOT NULL DEFAULT '',answer TEXT NOT NULL DEFAULT '',citations_json TEXT NOT NULL DEFAULT '[]',state TEXT NOT NULL,answer_kind TEXT NOT NULL DEFAULT '',completion_hash TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,created_ns INTEGER NOT NULL,terminal_ns INTEGER NOT NULL DEFAULT 0,lease_id TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',cancel_requested INTEGER NOT NULL DEFAULT 0,redacted INTEGER NOT NULL DEFAULT 0,permit_json TEXT NOT NULL,operation_json TEXT NOT NULL,plan_json TEXT,job_id TEXT NOT NULL DEFAULT '',invocation_ids_json TEXT NOT NULL DEFAULT '[]',rounds INTEGER NOT NULL DEFAULT 0,tool_calls INTEGER NOT NULL DEFAULT 0,current_page_json TEXT, english_question TEXT NOT NULL DEFAULT '');
CREATE TABLE turn_events(turn_id TEXT NOT NULL,sequence INTEGER NOT NULL,event_json TEXT NOT NULL,created_ns INTEGER NOT NULL,source_step TEXT,source_sequence INTEGER,PRIMARY KEY(turn_id,sequence),UNIQUE(turn_id,source_step,source_sequence));
CREATE TABLE feedback(turn_id TEXT NOT NULL,visitor_subject TEXT NOT NULL,answer_revision INTEGER NOT NULL,value TEXT NOT NULL,version INTEGER NOT NULL,PRIMARY KEY(turn_id,visitor_subject));
CREATE TABLE compactions(compaction_id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,source_generation INTEGER NOT NULL,compaction_json TEXT NOT NULL,state TEXT NOT NULL,lease_id TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',operation_json TEXT NOT NULL,UNIQUE(conversation_id,source_generation));
CREATE TABLE debug_turns(debug_id TEXT PRIMARY KEY,site_id TEXT NOT NULL,data_epoch TEXT NOT NULL,actor_id TEXT NOT NULL,debug_json TEXT NOT NULL,expires_ns INTEGER NOT NULL);
CREATE TABLE qa_receipts(site_id TEXT NOT NULL,data_epoch TEXT NOT NULL,actor_id TEXT NOT NULL,function_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,result_json TEXT NOT NULL,result_hash TEXT NOT NULL,created_ns INTEGER NOT NULL,PRIMARY KEY(site_id,data_epoch,actor_id,function_id,idempotency_key));
CREATE TABLE qa_publication_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL);
CREATE TABLE debug_events(debug_id TEXT NOT NULL,sequence INTEGER NOT NULL,event_json TEXT NOT NULL,PRIMARY KEY(debug_id,sequence));
CREATE INDEX turns_conversation ON turns(conversation_id,created_ns,turn_id);
INSERT INTO "qa_publication_state"("singleton","revision") VALUES(1,0);
PRAGMA user_version=7;
